  function snapshotButtonBank(ctrl,index){const count=Math.max(1,ctrl.actions.length),width=Math.min(38,118/count),gap=6,total=count*width+(count-1)*gap,start=(180-total)/2;return ctrl.actions.map((candidate,i)=>{const x=start+i*(width+gap),selected=i===index,label=String(candidate.label).replace(/[↶↷◀▶▲▼]/g,"").trim().slice(0,9);return `<rect class="${selected?"ink-solid":"ink-line"}" x="${x}" y="36" width="${width}" height="28" rx="2"/><text class="snapshot-tiny ${selected?"paper-text":""}" x="${x+width/2}" y="53" text-anchor="middle">${label}</text>`;}).join("");}
