    gunnery:{"weapon-safe":"GUARD CLOSED","weapon-bank":"COIL A","range-gate":"CENTERED","capacitor":"READY","weapon-arm":"SAFE"},
    engineering:{"breaker-bank":"NORMAL","bus-source":"PRIMARY","load-share":"BALANCED","coolant-valve":"METERED","pump-select":"A","bus-tie":"NORMAL"},
    science:{"receiver-band":"WIDEBAND","aperture":"MAIN ARRAY","receiver-gain":"NOMINAL","integration":"NOMINAL","emitter-inhibit":"CLOSED","emitter-gate":"SAFE"},
    comms:{"link-mode":"HAIL","carrier-path":"OMNI RF","channel-wheel":"HOME","frequency":"CENTERED","tx-power":"NOMINAL","crypto":"CLEAR","transmit-key":"SAFE"}
