  function requiredStateTargets(station,proc){const def=STATIONS[station],out=[];for(const token of proc.sequence){if(AUTH_TAIL.includes(token))continue;const hit=findAction(def,token);if(hit&&controlMode(station,hit.ctrl)!=="momentary")out.push({controlId:hit.ctrl.id,state:hit.action.state,token,label:controlIdentity(station,hit.ctrl).fullName});}return out;}
