  function initialState(){return {profile:HUMAN_PROFILE,simTime:0,velocity:12.4,heading:37,throttle:22,reactor:68,thermal:31,hull:100,track:42,comms:88,nav:74,weapons:61,driveHealth:100,sensorHealth:100,commsHealth:100,weaponHealth:100,coolingHealth:100,targetRange:42000,targetBearing:74,targetClosure:-1.7,targetClass:"unresolved",targetIFF:"unknown",emissions:18,firingSolution:0,courseCommitted:false,navDestination:"Rendezvous Alpha",navBurnDeltaV:2.1,commsChannel:"Fleet tactical",commsEncryption:true,weaponGroup:"Coil battery A",weaponMode:"safe",capacitors:54,engineeringFault:null,power:{...BASE_POWER},contact:{present:false,friendly:false,x:76,y:31},selectedProcedure:{helm:"planned-burn",navigation:"transfer-solve",gunnery:"fire-solution",engineering:"load-rebalance",science:"passive-track",comms:"authenticated-hail"},hardware:initialHardwareState(),procedure:null,relay:null,log:[]};}

  let state=initialState(),activeStation="helm",manualOpen=false,manualQuery="",timer=null,physicalGesture=null,suppressGestureClickUntil=0;
