  function stationContext(k){const f={helm:()=>Math.min(powerFactor("helm"),state.nav,state.driveHealth),navigation:()=>state.track*.45+state.comms*.35+powerFactor("navigation")*.2,gunnery:()=>Math.min(state.track,powerFactor("gunnery"),state.weaponHealth,100-Math.max(0,state.thermal-55)),engineering:()=>Math.min(powerFactor("engineering"),(state.driveHealth+state.coolingHealth+state.hull)/3),science:()=>Math.min(powerFactor("science"),state.sensorHealth,100-Math.max(0,state.thermal-70)),comms:()=>Math.min(powerFactor("comms"),state.commsHealth)};return clamp(f[k]?.()??60);}
