  function addLog(station,message){state.log.unshift({time:state.simTime,station,message});state.log=state.log.slice(0,100);renderLog();}
  const timeString=n=>`${String(Math.floor(n/60)).padStart(2,"0")}:${String(n%60).padStart(2,"0")}`;
  function selectedProcedure(key=activeStation){const d=STATIONS[key];return d.procedures.find(p=>p.id===state.selectedProcedure[key])||d.procedures[0];}

  function renderTopState(){const fields={velocity:`${round(state.velocity,1)} km/s`,reactor:`${round(state.reactor)}%`,thermal:`${round(state.thermal)}%`,hull:`${round(state.hull)}%`,track:`${round(state.track)}%`,comms:`${round(state.comms)}%`,nav:`${round(state.nav)}%`,weapons:`${round(state.weapons)}%`};Object.entries(fields).forEach(([k,v])=>{const t=$(`state-${k}`),m=$(`meter-${k}`);if(t)t.textContent=v;if(m)m.style.width=`${clamp(k==="velocity"?state.velocity*4:state[k])}%`;});if($("crew-profile-name"))$("crew-profile-name").textContent=state.profile.name;if($("crew-summary-rules"))$("crew-summary-rules").textContent="WoD-derived d10";if($("crew-summary-resolution"))$("crew-summary-resolution").textContent="DM adjudicated";if($("crew-summary-difficulty"))$("crew-summary-difficulty").textContent=state.relay?`Difficulty ${state.relay.difficulty}`:"pending";}
  function renderPowerControls(){$("power-controls").innerHTML=Object.keys(state.power).map(k=>`<div class="exo-power-control"><label><span>${STATIONS[k].label}</span><b>${state.power[k]}</b></label><input data-power="${k}" type="range" min="4" max="30" value="${state.power[k]}"></div>`).join("");const b=$("power-total");b.textContent=`${powerTotal()} / 100 visual points allocated`;b.dataset.over=powerTotal()>100?"true":"false";}
  function renderTabs(){$("station-tabs").innerHTML=Object.entries(STATIONS).map(([k,d])=>`<button class="exo-station-tab station-${d.theme}" type="button" data-station="${k}" aria-selected="${activeStation===k}">${d.label}<span class="tab-state">${d.procedures.length} operations</span></button>`).join("");}
  function tacticalDisplay(kind){const c=state.contact;return `<div class="exo-tactical-display display-${kind}" aria-label="${kind} visualization"><div class="exo-tactical-ring"></div><div class="exo-ownship"></div><div class="exo-contact ${c.friendly?"friend":""}" style="left:${c.x}%;top:${c.y}%;opacity:${c.present?1:0}"></div><span class="exo-display-caption">VISUAL ONLY // ${kind} // ${c.present?`${round(state.targetBearing)}° · ${Math.round(state.targetRange).toLocaleString()} km`:"no remote track"}</span></div>`;}

  function newProcedureState(){const station=activeStation,proc=selectedProcedure(station),startHardware={...state.hardware[station]},derived=deriveExpectedSequence(station,proc,startHardware);return {active:true,station,operationId:proc.id,inputs:[],startHardware,expectedSequence:derived.expected,preSatisfied:derived.preSatisfied,requiredPersistent:derived.requiredPersistent,authKey:"out",authLock:"safe",authShield:"closed",startedAt:state.simTime};}
  function displayValue(ctrl){return state.hardware[activeStation]?.[ctrl.id]??ctrl.default??"STANDBY";}
  function controlStatus(ctrl,p,active){const mode=controlMode(activeStation,ctrl),tokens=new Set(ctrl.actions.map(a=>a.token)),attempt=Boolean(active&&p?.active&&p.station===activeStation),requiredNow=attempt&&p.expectedSequence.some(token=>tokens.has(token)),preSet=attempt&&p.preSatisfied.some(token=>tokens.has(token)),persistent=p?.requiredPersistent?.find(item=>item.controlId===ctrl.id),satisfied=Boolean(persistent&&state.hardware[activeStation]?.[ctrl.id]===persistent.state),relevant=requiredNow||preSet||Boolean(persistent);const modeLabel=mode==="momentary"?"MOMENTARY":mode==="reset-execute"?"AUTO RESET":"LATCHED";let activity="idle",activityLabel="IDLE";if(attempt&&requiredNow){activity="live";activityLabel="LIVE";}else if(attempt&&relevant&&satisfied){activity="set";activityLabel="SET";}else if(attempt&&relevant){activity="required";activityLabel="REQUIRED";}return {mode,modeLabel,activity,activityLabel,satisfied,relevant};}
